          "passage": "青原市 レシピコンテスト\n1. 募集条件\n・以下の材料を2種類以上使用すること。それ以外の材料は自由です。\n  [ トマト、きゅうり、たまねぎ、なす、たまご、とり肉、米 ]\n・分量は二人分で、調理時間は30分以内、材料費は1,000円以内であること。\n・応募者自身が考えたレシピで、未発表のもの。\n2. 募集部門と応募資格\n・中学・高校生の部：市内在住の中学・高校生、または市内の中学校か高等学校に通う生徒\n・一般の部：市内在住の方（高校生以下を除く）、または市内で働いている方か、市内の大学に通う学生\n3. 応募方法\n・応募用紙に必要事項を記入のうえ、料理の写真を添付して提出。\n・応募は一人3品まで可能です。応募用紙1枚あたり1品のレシピを記入してください。\n4. 応募締め切りと提出方法\n・6月24日（金）必着で青原市役所農業課に郵送してください。\n※青原市の中学校・高等学校に通う生徒は、6月20日（月）までに在籍する学校に提出してください。",
